#!/usr/bin/env python3
"""Writes lib/rsasign.resid: RSA private-key operations (PKCS#1 v1.5
signatures, RFC 8017 §8.2.1) in constant time over Secret wide integers,
one copy per prime size class (1024, 1536 and 2048 bits: RSA-2048, -3072,
-4096 and anything up to those sizes).

    python3 tools/gen_rsasign.py
"""
import os

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
CLASSES = [1024, 1536, 2048]

HEAD = '''// lib/rsasign.resid — RSA signing (PKCS#1 v1.5, RFC 8017 §8.2.1) on secret
// keys, in constant time.
//
// GENERATED by tools/gen_rsasign.py: edit the generator, not this file.
//
// The private key (d, p, q and q^-1 mod p) is Secret throughout; the
// compiler checks that no branch, index, comparison or division depends on
// it. The method:
//   - CRT without a secret division: m^d mod p is m^(d mod (p-1)) mod p
//     (Fermat), so each half raises to the whole of d (every bit of its
//     public bit bound), and d mod (p-1) is never computed;
//   - Montgomery multiplication over one wide integer per class
//     (R = 2^K, K the class's prime size; products fit in 2K + 64 bits),
//     whose constants come from the prime in constant time: -p^-1 mod R by
//     Newton's iteration, R^2 mod p by 2K doublings each with a masked
//     subtraction;
//   - a Montgomery ladder over every bit of d with masked swaps;
//   - Garner's recombination with q^-1 mod p;
//   - the signature is checked with the public key before it is released
//     (a faulty CRT half would otherwise reveal a factor: Boneh, DeMillo
//     and Lipton 1997); a key whose check fails gives no signature.
// p and q must have the same bit length (as every RSA key generator makes
// them), so one masked subtraction reduces a value below q modulo p.
//
// Checked against Python's cryptography (tests/crypto/rsasign_test.resid,
// tools/gen_rsasign_ref.py) and under valgrind (tests/ct).

import "rsa.resid";
import "bignum.resid";
import "hash.resid";
import "word.resid";
'''

TEMPLATE = '''
// ─── Primes up to {K} bits (products in UInt({W})) ─────────────────────

UInt({W}) r{K}_zero() {{ return 0; }}
UInt({W}) r{K}_rmask() {{ return wrapping_usub((UInt({W})) 1 << (UInt({W})) {K}, (UInt({W})) 1); }}

Secret(UInt({W})) r{K}_mask(Secret(UInt({W})) bit) {{
    Secret(Int) h = ct_hide(wrapping_i64(bit & 1));
    return wrapping_usub(r{K}_zero(), (UInt({W})) wrapping_u64(h));
}}

// m all ones: a, else b.
Secret(UInt({W})) r{K}_sel(Secret(UInt({W})) m, Secret(UInt({W})) a, Secret(UInt({W})) b) {{ return b ^ ((a ^ b) & m); }}

// t - p if t >= p, else t (t < 2^({W} - 1)): the borrow is the top bit.
Secret(UInt({W})) r{K}_csub(Secret(UInt({W})) t, Secret(UInt({W})) p) {{
    Secret(UInt({W})) d = wrapping_usub(t, p);
    return r{K}_sel(r{K}_mask(d >> (UInt({W})) {Wm1}), t, d);
}}

// Montgomery reduction of T < 2pR: T R^-1 mod p (two subtractions cover
// T up to 3pR).
Secret(UInt({W})) r{K}_redc(Secret(UInt({W})) t, Secret(UInt({W})) p, Secret(UInt({W})) pinv) {{
    Secret(UInt({W})) m = wrapping_umul(t & r{K}_rmask(), pinv) & r{K}_rmask();
    Secret(UInt({W})) u = wrapping_uadd(t, wrapping_umul(m, p)) >> (UInt({W})) {K};
    return r{K}_csub(r{K}_csub(u, p), p);
}}

Secret(UInt({W})) r{K}_mont(Secret(UInt({W})) a, Secret(UInt({W})) b, Secret(UInt({W})) p, Secret(UInt({W})) pinv) {{
    return r{K}_redc(wrapping_umul(a, b), p, pinv);
}}

// -p^-1 mod R: x = x (2 - p x) doubles the bits of p^-1 that are right.
Secret(UInt({W})) r{K}_newton(Secret(UInt({W})) p, Secret(UInt({W})) x, Int i) {{
    if (i <= 0) {{ return wrapping_usub(r{K}_zero(), x) & r{K}_rmask(); }}
    Secret(UInt({W})) px = wrapping_umul(p, x) & r{K}_rmask();
    Secret(UInt({W})) two = classify((UInt({W})) 2);
    return r{K}_newton(p, wrapping_umul(x, wrapping_usub(two, px)) & r{K}_rmask(), i - 1);
}}

// 2^n mod p from 1 by n doublings.
Secret(UInt({W})) r{K}_pow2(Secret(UInt({W})) r, Secret(UInt({W})) p, Int n) {{
    if (n <= 0) {{ return r; }}
    return r{K}_pow2(r{K}_csub(r << (UInt({W})) 1, p), p, n - 1);
}}

type R{K}Pair = {{ Secret(UInt({W})) a; Secret(UInt({W})) b; }};

// The ladder from bit i of d down to bit 0: (r0, r1) = (b^k, b^(k+1)).
R{K}Pair r{K}_ladder(Secret(UInt({W})) d, Int i, R{K}Pair r, Secret(UInt({W})) p, Secret(UInt({W})) pinv) {{
    if (i < 0) {{ return r; }}
    Secret(UInt({W})) m = r{K}_mask(d >> (UInt({W})) i);
    Secret(UInt({W})) x0 = r{K}_sel(m, r.b, r.a);
    Secret(UInt({W})) x1 = r{K}_sel(m, r.a, r.b);
    Secret(UInt({W})) y1 = r{K}_mont(x0, x1, p, pinv);
    Secret(UInt({W})) y0 = r{K}_mont(x0, x0, p, pinv);
    return r{K}_ladder(d, i - 1, R{K}Pair {{.a = r{K}_sel(m, y1, y0), .b = r{K}_sel(m, y0, y1)}}, p, pinv);
}}

// m^d mod p for a public m < 2^(2K), d < 2^(2K).
Secret(UInt({W})) r{K}_half(UInt({W}) m, Secret(UInt({W})) d, Secret(UInt({W})) p) {{
    Secret(UInt({W})) pinv = r{K}_newton(p, classify((UInt({W})) 1), 12);
    Secret(UInt({W})) rr = r{K}_pow2(classify((UInt({W})) 1), p, {K2});
    Secret(UInt({W})) mp = r{K}_mont(r{K}_redc(classify(m), p, pinv), rr, p, pinv);
    Secret(UInt({W})) base = r{K}_mont(mp, rr, p, pinv);
    Secret(UInt({W})) one = r{K}_mont(classify((UInt({W})) 1), rr, p, pinv);
    R{K}Pair r = r{K}_ladder(d, {K2m1}, R{K}Pair {{.a = one, .b = base}}, p, pinv);
    return r{K}_redc(r.a, p, pinv);
}}

Secret(UInt({W})) r{K}_of(List(Secret(UInt(8))) b, Int i, Secret(UInt({W})) acc) {{
    if (i >= b.len()) {{ return acc; }}
    return r{K}_of(b, i + 1, (acc << (UInt({W})) 8) | (UInt({W})) b[i]);
}}

UInt({W}) r{K}_pub(List(Int) b, Int i, UInt({W}) acc) {{
    if (i >= b.len()) {{ return acc; }}
    return r{K}_pub(b, i + 1, (acc << (UInt({W})) 8) | (UInt({W})) wrapping_u64(b[i] & 255));
}}

List(Int) r{K}_bytes(UInt({W}) x, Int n, Int i, ListBuf(Int) acc) {{
    if (i >= n) {{ return acc.finish(); }}
    return r{K}_bytes(x, n, i + 1, acc.push(wrapping_i64((x >> (UInt({W})) (8 * (n - 1 - i))) & 255)));
}}

// The CRT signature s = m^d mod n, k bytes, published.
@requires(declassify)
List(Int) r{K}_sign_em(List(Int) em, Int k, List(Secret(UInt(8))) d, List(Secret(UInt(8))) p, List(Secret(UInt(8))) q, List(Secret(UInt(8))) iqmp) {{
    UInt({W}) m = r{K}_pub(em, 0, r{K}_zero());
    Secret(UInt({W})) sd = r{K}_of(d, 0, classify(r{K}_zero()));
    Secret(UInt({W})) sp = r{K}_of(p, 0, classify(r{K}_zero()));
    Secret(UInt({W})) sq = r{K}_of(q, 0, classify(r{K}_zero()));
    Secret(UInt({W})) si = r{K}_of(iqmp, 0, classify(r{K}_zero()));
    Secret(UInt({W})) mp = r{K}_half(m, sd, sp);
    Secret(UInt({W})) mq = r{K}_half(m, sd, sq);
    Secret(UInt({W})) pinv = r{K}_newton(sp, classify((UInt({W})) 1), 12);
    Secret(UInt({W})) rr = r{K}_pow2(classify((UInt({W})) 1), sp, {K2});
    // h = q^-1 (mp - mq) mod p; mq < q < 2p, so one subtraction reduces it.
    Secret(UInt({W})) diff = r{K}_csub(wrapping_uadd(mp, wrapping_usub(sp, r{K}_csub(mq, sp))), sp);
    Secret(UInt({W})) h = r{K}_mont(r{K}_mont(diff, si, sp, pinv), rr, sp, pinv);
    Secret(UInt({W})) s = wrapping_uadd(mq, wrapping_umul(h, sq));
    UInt({W}) out = ct_public(declassify(s, "an RSA signature, checked against the public key before anyone receives it"));
    return r{K}_bytes(out, k, 0, ListBuf());
}}
'''

TAIL = '''
// ─── Entry ──────────────────────────────────────────────────────────

Int bytes_of_bits(Int bits) { return (bits + 7) / 8; }

Int lead_zeros(List(Int) b, Int i) {
    if (i >= b.len() || b[i] != 0) { return i; }
    return lead_zeros(b, i + 1);
}

/// The PKCS#1 v1.5 signature of `msg` with hash `h` (Sha256 or Sha512 for
/// SSH's rsa-sha2-256 and rsa-sha2-512), for the key (n, e, d, p, q,
/// q^-1 mod p) with big-endian magnitudes, the private ones Secret. Empty
/// when the key is malformed or larger than 4096 bits, its primes differ
/// in bit length, or the signature does not verify under (n, e).
@requires(declassify)
pub List(Int) rsa_pkcs1_sign(HashAlg h, List(Int) n0, List(Int) e, List(Secret(UInt(8))) d, List(Secret(UInt(8))) p, List(Secret(UInt(8))) q, List(Secret(UInt(8))) iqmp, List(Int) msg) {
    List(Int) n = n0[lead_zeros(n0, 0)..n0.len()];
    Int k = n.len();
    if (k < 128 || k > 512 || (n[k - 1] & 1) == 0 || e.len() == 0 || d.len() > k || p.len() != q.len() || p.len() * 2 < k - 1 || p.len() * 2 > k + 1 || iqmp.len() > p.len()) { return []; }
    List(Int) em = rsa_pkcs1_em(h, hash_bytes(h, msg), k);
    if (em.len() != k) { return []; }
    Int pb = p.len() * 8;
    List(Int) s = if (pb <= 1024) { r1024_sign_em(em, k, d, p, q, iqmp) } else { if (pb <= 1536) { r1536_sign_em(em, k, d, p, q, iqmp) } else { r2048_sign_em(em, k, d, p, q, iqmp) } };
    RsaPub pk = rsa_pub(n, e);
    return if (pk.ok && rsa_pkcs1_verify(h, pk, msg, s)) { s } else { [] };
}
'''

out = [HEAD]
for K in CLASSES:
    W = 2 * K + 64
    out.append(TEMPLATE.format(K=K, W=W, Wm1=W - 1, K2=2 * K, K2m1=2 * K - 1))
out.append(TAIL)
open(os.path.join(ROOT, 'lib', 'rsasign.resid'), 'w').write(''.join(out))
print('wrote lib/rsasign.resid')
